  // ---- About page ----
  "about.hero.eyebrow": "دەربارەی چیا",
  "about.hero.title": "دەربارەی چیا",
  "about.hero.sub": "چیا ئیستەیت ماڵی خانووبەرەیە لە کوردستان — کە هەموو ڕیکلامێک پشکنراوە، هەموو نرخێک ڕاستە، و هەموو بریکارێک بەرپرسیارە. کڕیار، بەکرێگر و پسپۆڕی ناوخۆیی جێباوەڕ لە یەک شوێنی ئارام و ڕووندا کۆدەکەینەوە، تاوەکو دۆزینەوەی ماڵ ڕوون بێت نەک ماندووکەر.",
  "about.stat.listings.value": "١٢,٠٠٠+",
  "about.stat.listings.label": "لیستە چالاکەکان",
