  "about.stat.cities.value": "٩",
  "about.stat.cities.label": "شاری داپۆشراو",
  "about.stat.years.value": "٦",
  "about.stat.years.label": "ساڵ متمانە",
  "about.story.eyebrow": "چیرۆکەکەمان",
  "about.story.title": "گەڕانێک بۆ ماڵ کە ڕێز لە کاتت دەگرێت",
  "about.story.p1": "چیا بە بێزارییەکی سادەوە دەستیپێکرد: دۆزینەوەی ماڵ لە هەرێمەکەدا بە واتای لیستی پەرشوبڵاو، نرخی نادیار و پەیوەندی بێکۆتایی بوو. ئێمە هەستاین بە دروستکردنی شتێکی باشتر — یەک شوێن کە هەر ماڵێک ڕاستەقینە بێت، هەر نرخێک ڕاستگۆ بێت و هەر بریکارێک بەرپرسیار بێت.",
  "about.story.p2": "ئەمڕۆ هەزاران لیستی پشتڕاستکراو و تۆڕێک لە بریکاری ناوخۆیی کۆدەکەینەوە کە گەڕەکەکانیان شەقام بە شەقام دەناسن. جا یەکەم شوقەت دەکڕیت یان ڤێلایەکی خێزانی بەکرێ دەگریت، چیا دروستکراوە بۆ ئەوەی گەشتەکە ڕوون و ئارام بکات.",
  "about.values.title": "بۆ چی ڕادەوەستین",
  "about.values.sub": "ئەو بنەماییانەی لە پشت هەر لیست، پەیام و بینینێکی چیاوەن.",
  "about.value.0.title": "پشتڕاستکراو و ڕاستەقینە",
  "about.value.0.desc": "هەر لیست و بریکارێک پێداچوونەوەی بۆ دەکرێت، بۆیە ئەوەی دەیبینیت ئەوەیە کە سەردانی دەکەیت.",
  "about.value.1.title": "ڕوونی ڕەهەندی",
  "about.value.1.desc": "نرخی ڕوون، وردەکاری ڕاستگۆ و بێ کرێی شاراوە — لە گەڕانەوە تا واژۆکردن.",
  "about.value.2.title": "خەڵک لە پێشەوە",
  "about.value.2.desc": "بریکاری ڕاستەقینە و پشتگیری ڕاستەقینە، لە هەر هەنگاوێکدا ڕێنماییت دەکەن.",
  "about.value.3.title": "شارەزایی ناوخۆیی",
  "about.value.3.desc": "بریکارانێک کە لەو گەڕەکانەدا دەژین و کاردەکەن کە تۆ لێی دەگەڕێیت.",
  "about.cta.title": "ئامادەیت شوێنی خۆت بدۆزیتەوە؟",
  "about.cta.sub": "گەڕان بەناو هەزاران ماڵدا لە سەرانسەری هەرێمەکە، یان قسە لەگەڵ تیمەکەمان بکە دەربارەی لیستکردنی هی خۆت.",
  "about.cta.browse": "گەڕان بەناو خانووبەرەکاندا",
